""" Check if the given list has unique elements
        Uses the property of sets:
        If converted into a set it is guaranteed to have unique elements.
        -> Compare number of elements to determine if the list contains duplicates
    """
def has_duplicates(n: Any) -> object {
    if (`type(n) is not `list) {
        raise TypeError("Given input is not a list");
    }
    if (len(n) != len(`set(n))) {
        return True;
    }
    return False;
}

"""
    Convert string to float or NaN for "NA" for missing data

    Parameters:
       s  - string representation of integer or "NA"

    Return value:
      integer value of s or NA_VALUE
    """
def float_or_na(s: Any) -> object {
    return float("NaN") if (s == "NA") else float(s);
}

